/**
 * Returns the `n` of every item, upper-cased when the item's `a` flag is 1.
 * null/undefined items are skipped.
 */
function proc(items) {
  return items
    .filter((item) => item != null)
    .map((item) => (item.a == 1 ? item.n.toUpperCase() : item.n));
}

/**
 * Splits a comma-separated string into trimmed, non-empty parts.
 * e.g. " a, b,,c " -> ["a", "b", "c"]
 */
function f2(text) {
  return text
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part !== '');
}

module.exports = { proc, f2 };

